import React from "react";
import { Link } from "react-router-dom";

class ChatListItem extends React.Component {
    render() {

        return (
            <div className="col-12 col-md-4 mb-4">
                <Link to={"/chat/"} className="card h-100 shadow-sm text-decoration-none text-dark">
                    <div className="card-body d-flex align-items-center item-back boder">
                        
                        <img
                            src='img/aaa.png'
                            alt="avatar"
                            className="rounded-circle me-3"
                            width="60"
                            height="60"
                        />

                        <div className="flex-grow-1 text-color">
                            <div className="fw-bold">name</div>
                            <div className="text-muted small text-color">last masange</div>
                        </div>

                    </div>
                </Link>
            </div>
        );
    }
}

export default ChatListItem;
